{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.inwards_base_table_for_refer as with a as ( SELECT UPPER( CASE WHEN REGEXP_LIKE( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-.*\', \'i\' ) THEN REGEXP_SUBSTR( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-([^-]+-[^-]+)\', 1, 1, \'ie\', 1 ) ELSE REVERSE( SUBSTRING( REVERSE(TRIM(\"Item Type skuCode\")), CHARINDEX(\'-\', REVERSE(TRIM(\"Item Type skuCode\"))) + 1, LEN(TRIM(\"Item Type skuCode\")) ) ) END ) AS SKU_group, CASE WHEN REGEXP_LIKE( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-.*\', \'i\' ) THEN TRY_TO_NUMBER( REGEXP_SUBSTR( TRIM(\"Item Type skuCode\"), \'^PP([0-9]+)-\', 1, 1, \'ie\', 1 ) ) ELSE 1 END mul, LOWER(FINAL_TYPE) type, \"PUTAWAY_UPDATED\"::DATE as date, CASE WHEN REGEXP_LIKE( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-.*\', \'i\' ) THEN TRY_TO_NUMBER( REGEXP_SUBSTR( TRIM(\"Item Type skuCode\"), \'^PP([0-9]+)-\', 1, 1, \'ie\', 1 ) ) ELSE 1 END * SUM(\"PUTAWAY_COMPLETED_QUANTITY\") qty, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") r_qty, FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1, 2, 3, 4 HAVING qty >= 50 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, max(cogs) as cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ) select date, sku_group, l1_category, category, meta1, meta2, meta3, sum(qty * cogs) cogs_value, sum(qty) qty from a left join meta_map on sku_group_clean = UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) where l1_category is not null group by 1, 2, 3, 4, 5, 6, 7; create or replace table snitch_db.maplemonk.inv_table_to_refer as WITH wh_inv_raw AS ( SELECT date, TRIM(UPPER(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) + 1)))) AS sku_group, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(\"Item SkuCode\"), 1, POSITION(\'-\' IN REVERSE(\"Item SkuCode\")) - 1)))) AS raw_size, SUM(inventory) + SUM(COALESCE(\"Inventory Blocked\", 0)) + SUM(COALESCE(\"Inventory Not Synced\", 0)) + SUM(COALESCE(\"Pending Inventory Assessment\", 0)) + SUM(COALESCE(\"Putaway Pending\", 0)) + SUM(COALESCE(\"Putback Pending\", 0)) + SUM(COALESCE(\"Stock In Transfer\", 0)) AS inv_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE facility IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') GROUP BY 1, 2, 3 ), offline_sizes AS ( SELECT date, SKU_GROUP AS sku_group, \'XS\' AS raw_size, COALESCE(XS_UNITS, 0) + COALESCE(JIT_XS_UNITS, 0) AS inv_qty FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'S\', COALESCE(S_UNITS, 0) + COALESCE(JIT_S_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'M\', COALESCE(M_UNITS, 0) + COALESCE(JIT_M_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'L\', COALESCE(L_UNITS, 0) + COALESCE(JIT_L_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'XL\', COALESCE(XL_UNITS, 0) + COALESCE(JIT_XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'2XL\', COALESCE(XXL_UNITS, 0) + COALESCE(JIT_2XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'3XL\', COALESCE(XL3_UNITS, 0) + COALESCE(JIT_3XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'4XL\', COALESCE(XL4_UNITS, 0) + COALESCE(JIT_4XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'5XL\', COALESCE(XL5_UNITS, 0) + COALESCE(JIT_5XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'6XL\', COALESCE(XL6_UNITS, 0) + COALESCE(JIT_6XL_UNITS, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 UNION ALL SELECT date, SKU_GROUP, \'FREE SIZE\', COALESCE(inventory, 0) + COALESCE(JIT_QTY, 0) FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE COALESCE(XS_UNITS,0)+COALESCE(JIT_XS_UNITS,0) + COALESCE(S_UNITS,0)+COALESCE(JIT_S_UNITS,0) + COALESCE(M_UNITS,0)+COALESCE(JIT_M_UNITS,0) + COALESCE(L_UNITS,0)+COALESCE(JIT_L_UNITS,0) + COALESCE(XL_UNITS,0)+COALESCE(JIT_XL_UNITS,0) + COALESCE(XXL_UNITS,0)+COALESCE(JIT_2XL_UNITS,0) + COALESCE(XL3_UNITS,0)+COALESCE(JIT_3XL_UNITS,0) + COALESCE(XL4_UNITS,0)+COALESCE(JIT_4XL_UNITS,0) + COALESCE(XL5_UNITS,0)+COALESCE(JIT_5XL_UNITS,0) + COALESCE(XL6_UNITS,0)+COALESCE(JIT_6XL_UNITS,0) = 0 ), store_inv AS ( SELECT date, UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(raw_size)) AS raw_size, SUM(inv_qty) AS inv_qty FROM offline_sizes GROUP BY 1, 2, 3 ), myntra AS ( WITH base AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(date), \'\'), \'DD-MM-YYYY\') AS date_col, gtin, soh FROM snitch_db.maplemonk.s3_myntra_inventory_test ) SELECT b.date_col AS date, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(lm.sku), CHARINDEX(\'-\', REVERSE(lm.sku)) + 1, LEN(lm.sku))))) AS sku_group, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(lm.sku), 1, CHARINDEX(\'-\', REVERSE(lm.sku)) - 1)))) AS raw_size, SUM(COALESCE(b.soh, 0)) AS inv_qty FROM base b LEFT JOIN snitch_db.maplemonk.logic_final_item_master lm ON lm.ean = b.gtin GROUP BY 1, 2, 3 ), flipkart AS ( WITH base AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(date), \'\'), \'DD-MM-YYYY\') AS date_col, style_code, size AS raw_size, atp FROM snitch_db.maplemonk.s3_flipkart_inventory_test ) SELECT date_col AS date, UPPER(TRIM(style_code)) AS sku_group, UPPER(TRIM(raw_size)) AS raw_size, SUM(COALESCE(atp, 0)) AS inv_qty FROM base GROUP BY 1, 2, 3 ), date_spine AS ( SELECT DATEADD( DAY, ROW_NUMBER() OVER (ORDER BY SEQ4()) - 1, \'2026-10-01\'::DATE )::DATE AS date FROM TABLE(GENERATOR(ROWCOUNT => 5000)) QUALIFY date <= CURRENT_DATE() ), myntra_intervals AS ( SELECT date AS snapshot_date, LEAD(date) OVER ( PARTITION BY sku_group, raw_size ORDER BY date ) AS next_snapshot_date, sku_group, raw_size, inv_qty FROM myntra WHERE date IS NOT NULL ), myntra_filled AS ( SELECT d.date, m.sku_group, m.raw_size, m.inv_qty FROM myntra_intervals m JOIN date_spine d ON d.date >= m.snapshot_date AND d.date < COALESCE(m.next_snapshot_date, DATEADD(DAY, 1, CURRENT_DATE())) ), flipkart_intervals AS ( SELECT date AS snapshot_date, LEAD(date) OVER ( PARTITION BY sku_group, raw_size ORDER BY date ) AS next_snapshot_date, sku_group, raw_size, inv_qty FROM flipkart WHERE date IS NOT NULL ), flipkart_filled AS ( SELECT d.date, f.sku_group, f.raw_size, f.inv_qty FROM flipkart_intervals f JOIN date_spine d ON d.date >= f.snapshot_date AND d.date < COALESCE(f.next_snapshot_date, DATEADD(DAY, 1, CURRENT_DATE())) ), inv_by_channel AS ( SELECT date, sku_group, raw_size, \'Warehouse\' AS channels, inv_qty FROM wh_inv_raw UNION ALL SELECT date, sku_group, raw_size, \'Offline\' AS channels, inv_qty FROM store_inv UNION ALL SELECT date, sku_group, raw_size, \'Myntra SOR\' AS channels, inv_qty FROM myntra_filled UNION ALL SELECT date, sku_group, raw_size, \'flipkart SOR\' AS channels, inv_qty FROM flipkart_filled ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END), MIN(CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END), MIN(a.l1_category) ) AS l1_category FROM snitch_db.maplemonk.meta_mapping_cogs_sku_2 a GROUP BY 1 ), pp_pattern AS ( SELECT \'REG\' AS grp, \'6\' AS pack, \'S\' AS size, 1 AS mult UNION ALL SELECT \'REG\', \'6\', \'M\', 2 UNION ALL SELECT \'REG\', \'6\', \'L\', 2 UNION ALL SELECT \'REG\', \'6\', \'XL\', 1 UNION ALL SELECT \'REG\', \'4\', \'S\', 1 UNION ALL SELECT \'REG\', \'4\', \'M\', 1 UNION ALL SELECT \'REG\', \'4\', \'L\', 1 UNION ALL SELECT \'REG\', \'4\', \'XL\', 1 UNION ALL SELECT \'PLUS\', \'6\', \'3XL\', 1 UNION ALL SELECT \'PLUS\', \'6\', \'4XL\', 2 UNION ALL SELECT \'PLUS\', \'6\', \'5XL\', 2 UNION ALL SELECT \'PLUS\', \'6\', \'6XL\', 1 UNION ALL SELECT \'PLUS\', \'4\', \'3XL\', 1 UNION ALL SELECT \'PLUS\', \'4\', \'4XL\', 1 UNION ALL SELECT \'PLUS\', \'4\', \'5XL\', 1 UNION ALL SELECT \'PLUS\', \'4\', \'6XL\', 1 ), pp_base AS ( SELECT date, channels, sku_group AS original_sku_group, SPLIT_PART(sku_group, \'-\', 2) || \'-\' || SPLIT_PART(sku_group, \'-\', 3) AS base_group, IFF(TRY_TO_NUMBER(SUBSTR(SPLIT_PART(sku_group, \'-\', 1), 3)) = 4, \'4\', \'6\') AS pack, SUM(inv_qty) AS packs FROM inv_by_channel WHERE sku_group LIKE \'PP%\' GROUP BY 1, 2, 3, 4, 5 ), pp_cat AS ( SELECT p.*, IFF(UPPER(TRIM(m.l1_category)) = \'PLUS\', \'PLUS\', \'REG\') AS grp FROM pp_base p LEFT JOIN meta_map m ON m.sku_group_clean = UPPER( IFF( UPPER(REPLACE(p.base_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(p.base_group, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE(REPLACE(p.base_group, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\'), REGEXP_REPLACE(REPLACE(p.base_group, \' \', \'\'), \'-.*$\', \'\') ) ) ), pp_exploded AS ( SELECT c.date, c.base_group AS sku_group, c.original_sku_group, c.channels, t.size, c.packs * t.mult AS inv_qty FROM pp_cat c JOIN pp_pattern t ON t.grp = c.grp AND t.pack = c.pack ), inv_norm AS ( SELECT date, sku_group, sku_group AS original_sku_group, CASE WHEN raw_size IS NULL OR TRIM(raw_size) = \'\' THEN \'L\' WHEN raw_size = \'01M\' THEN \'M\' WHEN raw_size = \'01XL\' THEN \'XL\' WHEN raw_size = \'06XL\' THEN \'6XL\' WHEN raw_size IN (\'XS\', \'S\', \'M\', \'L\', \'XL\') THEN raw_size WHEN raw_size IN (\'XXL\', \'2XL\', \'XXU\') THEN \'2XL\' WHEN raw_size IN (\'XXXL\', \'3XL\') THEN \'3XL\' WHEN raw_size IN (\'4XL\', \'5XL\', \'6XL\', \'7XL\', \'8XL\') THEN raw_size WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'2XL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' WHEN raw_size = \'39\' THEN \'2XL\' WHEN raw_size = \'41\' THEN \'4XL\' WHEN raw_size = \'43\' THEN \'5XL\' WHEN raw_size = \'45\' THEN \'6XL\' WHEN raw_size = \'1\' THEN \'XS\' WHEN raw_size = \'2\' THEN \'S\' WHEN raw_size = \'3\' THEN \'M\' WHEN raw_size = \'4\' THEN \'L\' WHEN raw_size = \'5\' THEN \'XL\' WHEN raw_size = \'6\' THEN \'2XL\' ELSE raw_size END AS size, channels, inv_qty FROM inv_by_channel WHERE sku_group NOT LIKE \'PP%\' ), inv_final AS ( SELECT date, sku_group, original_sku_group, channels, size, inv_qty FROM inv_norm UNION ALL SELECT date, sku_group, original_sku_group, channels, size, inv_qty FROM pp_exploded ) SELECT date, sku_group, channels, size, SUM(inv_qty) AS inv FROM inv_final GROUP BY 1, 2, 3, 4 HAVING SUM(inv_qty) > 0; create or replace table snitch_db.maplemonk.putaway_base_table as with a as ( SELECT UPPER( CASE WHEN REGEXP_LIKE( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-.*\', \'i\' ) THEN REGEXP_SUBSTR( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-([^-]+-[^-]+)\', 1, 1, \'ie\', 1 ) ELSE REVERSE( SUBSTRING( REVERSE(TRIM(\"Item Type skuCode\")), CHARINDEX(\'-\', REVERSE(TRIM(\"Item Type skuCode\"))) + 1, LEN(TRIM(\"Item Type skuCode\")) ) ) END ) AS SKU_group, CASE WHEN REGEXP_LIKE( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-.*\', \'i\' ) THEN TRY_TO_NUMBER( REGEXP_SUBSTR( TRIM(\"Item Type skuCode\"), \'^PP([0-9]+)-\', 1, 1, \'ie\', 1 ) ) ELSE 1 END mul, LOWER(FINAL_TYPE) type, \"PUTAWAY_UPDATED\"::DATE as date, CASE WHEN REGEXP_LIKE( TRIM(\"Item Type skuCode\"), \'^PP[0-9]+-.*\', \'i\' ) THEN TRY_TO_NUMBER( REGEXP_SUBSTR( TRIM(\"Item Type skuCode\"), \'^PP([0-9]+)-\', 1, 1, \'ie\', 1 ) ) ELSE 1 END * SUM(\"PUTAWAY_COMPLETED_QUANTITY\") qty, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") r_qty, FROM snitch_db.maplemonk.putaway_tracking GROUP BY 1, 2, 3, 4 HAVING qty >= 50 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, max(cogs) as cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku a GROUP BY 1 ) select date, type, sku_group, l1_category, category, meta1, meta2, meta3, sum(qty * cogs) cogs_value, sum(qty) qty from a left join meta_map on sku_group_clean = UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) where l1_category is not null group by 1, 2, 3, 4, 5, 6, 7,8; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.sales_data_view_for_refer as with params as ( select dateadd(day, -1, current_date()) as as_of_date, date_trunc(\'month\', dateadd(day, -1, current_date())) as as_of_month, day(dateadd(day, -1, current_date())) as cutoff_day ), main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger, _airbyte_data:\"Entity\"::STRING AS entity, _airbyte_data:\"Facility\"::STRING AS facility, NULLIF( _airbyte_data:\"GRN Price Without Tax\"::STRING, \'\' )::FLOAT AS grn_price_without_tax, NULLIF(_airbyte_data:\"MRP\"::STRING, \'\')::FLOAT AS mrp, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date, TRY_TO_DATE( _airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\' ) AS original_invoice_date, _airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code, NULLIF(_airbyte_data:\"Quantity\"::STRING, \'\')::INTEGER AS quantity, _airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number, NULLIF(_airbyte_data:\"Sales\"::STRING, \'\')::FLOAT AS sales, NULLIF(_airbyte_data:\"Total\"::STRING, \'\')::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING, _airbyte_data:\"Product SKU Code\"::STRING, _airbyte_data:\"Warehouse Name\"::STRING, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 union all select channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, to_date(Original_Invoice_Date, \'DD-MM-YYYY\') as original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 union all SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING AS channel_ledger, GET(VARIANT_COL, \'Entity\')::STRING AS entity, GET(VARIANT_COL, \'Facility\')::STRING AS facility, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT AS grn_price_without_tax, GET(VARIANT_COL, \'MRP\')::FLOAT AS mrp, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP AS original_created_date, TO_DATE( GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\' ) as original_invoice_date, GET(VARIANT_COL, \'Product SKU Code\')::STRING AS product_sku_code, GET(VARIANT_COL, \'Quantity\')::INT AS quantity, GET(VARIANT_COL, \'Sale Order Number\')::STRING AS sale_order_number, GET(VARIANT_COL, \'Sales\')::FLOAT AS sales, GET(VARIANT_COL, \'Total\')::FLOAT AS total FROM snitch_db.MAPLEMONK.mis_feb_20260504 union all select channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, to_date(Original_Invoice_Date, \'DD-MM-YYYY\') as original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total from snitch_db.MAPLEMONK.MIS_20260428 ), cost_price_map as ( select sku_group, cost_price, category from SNITCH_DB.MAPLEMONK.base_product qualify row_number() over ( partition by sku_group order by cost_price desc ) = 1 ), cat_mp as ( select case when left(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)), \'-\', 0) else UPPER(TRIM(SKUGROUP)) end as sku_group, case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\', \'Chinos\') then \'Trousers\' else category end as category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over ( partition by case when left(UPPER(TRIM(SKUGROUP)), 2) = \'BP\' then split_part(UPPER(TRIM(SKUGROUP)), \'-\', 0) else UPPER(TRIM(SKUGROUP)) end order by case when category = \'Jacket\' then \'Jackets\' when category = \'Jacket\' then \'Jackets\' when category in ( \'PYJAMAS\', \'Night Suit & Pyjamas\', \'Joggers & Trackpants\', \'Trackpants\', \'JOGGERS\' ) then \'Joggers & Trackpants\' when category = \'Shirt\' then \'Shirts\' when category = \'Sweater\' then \'Sweaters\' when category = \'T-Shirt\' then \'T-Shirts\' when category in (\'Trouser\', \'Chinos\') then \'Trousers\' else category end asc ) = 1 ), shopify_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, \'Shopify\' as Channel, sum(quantity)::int as quantity, sum(sales)::int as sales, sum((mrp * quantity))::int as mrp, sum(total)::int as total, sum( coalesce( try_to_number( nullif( regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\' ) ), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) )::int as cost_price from main where channel_ledger = \'Snitch\' and entity = \'NEW_INVOICE\' group by 1, 2, 3, 4 ), shopify_net as ( select \"Display Order Number\" as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where \"Channel Ledger\" = \'Snitch\' group by 1, 2 ), shopify as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, case when ifnull(b.return_qty, 0) > quantity then \'false\' else \'true\' end as flag, sales * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_sales, mrp * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_mrp, total * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_total, cost_price * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_cost_price from shopify_gross a left join shopify_net b on a.order_name = b.order_name and a.sku_group = b.sku_group ), shopify_main as ( select a.date, a.sku_group, b.category, \'Shopify\' Channel, sum(quantity) as quantity, sum(quantity - return_qty) as net_quantity, sum(total) as sales, sum(net_total) as net_sales, sum(mrp - total) as discount, sum(net_mrp - net_total) as net_discount, sum(a.cost_price) as cost_price, sum(net_cost_price) as net_cost_price from shopify a left join cost_price_map b on a.sku_group = b.sku_group group by 1, 2, 3, 4 ), mp_gross as ( select original_invoice_date as date, sale_order_number as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, case when channel_ledger in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) then \'MP_Ajio\' when channel_ledger in (\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\') then \'MP_Amazon\' when channel_ledger in ( \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\' ) then \'MP_Flipkart_PPMP\' when channel_ledger in ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) then \'MP_Myntra_PPMP\' when channel_ledger in ( \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) then \'MP_Nykaa\' else \'others\' end as Channel, sum(quantity) as quantity, sum( case when channel_ledger in ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) then total when channel_ledger in ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) and original_invoice_date >= \'2026-03-26\' then total + quantity * coalesce(avg_cat_charges,0) when channel_ledger in ( \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\' ) then total when channel_ledger in ( \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\' ) then (total / 0.82)::INT when channel_ledger in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\' ) then (total / 0.68)::INT ELSE SALES END )::int AS SALES, sum( coalesce( try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) ) as MRP, sum( coalesce( try_to_number( nullif( regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\' ) ), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) ) as cp from main a left join cost_price_map b on trim( upper( REVERSE( SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.p