(NULLIF(REPLACE(TRIM(units::VARCHAR), \',\', \'\'), \'\'))) AS net_quantity, SUM(TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(SP_Qty::VARCHAR), \',\', \'\'), \'\'))) AS sales, SUM(TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(SP_Qty::VARCHAR), \',\', \'\'), \'\'))) AS net_sales, SUM( TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(\"MRP Rev\"::VARCHAR), \',\', \'\'), \'\')) - TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(SP_QTY_EXCL_GST::VARCHAR), \',\', \'\'), \'\')) ) AS discount, SUM( TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(\"MRP Rev\"::VARCHAR), \',\', \'\'), \'\')) - TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(SP_QTY_EXCL_GST::VARCHAR), \',\', \'\'), \'\')) ) AS net_discount, SUM(TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(COGS_UNITS::VARCHAR), \',\', \'\'), \'\'))) AS cost_price, SUM(TRY_TO_NUMBER(NULLIF(REPLACE(TRIM(COGS_UNITS::VARCHAR), \',\', \'\'), \'\'))) AS net_cost_price FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a LEFT JOIN cat_mp b ON UPPER(TRIM(a.STYLE)) = b.sku_group LEFT JOIN mp_cat c ON UPPER(TRIM(a.STYLE)) = c.sku_group GROUP BY 1, 2, 3, 4 ) , slikk as ( select TO_DATE(order_date, \'DD-MM-YYYY\') AS date, upper(trim(a.\"Style \")) as sku_group, coalesce(b.category, c.category) as category, \'MP_slikk\' as channel, sum(total_quantity) as quantity, sum(total_quantity) as net_quantity, sum(total_amount) as sales, sum(total_amount) as net_sales, sum((mrp * total_quantity) - total_amount) as discount, sum((mrp * total_quantity) - total_amount) as net_discount, sum(\"COGSxQty \") as cost_price, sum(\"COGSxQty \") as net_cost_price from snitch_db.maplemonk.google_sheets_slikk a left join cat_mp b on upper(trim(a.\"Style \")) = b.sku_group left join mp_cat c on upper(trim(a.\"Style \")) = c.sku_group group by 1, 2, 3, 4 ) , mp_gross_sor as ( select original_invoice_date as date, sale_order_number as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(product_sku_code), CHARINDEX(\'-\', REVERSE(product_sku_code)) + 1, LEN(product_sku_code) ) ) ) ) AS sku_group, channel_ledger as Channel, sum(quantity) as quantity, sum(total)::int AS SALES, sum( coalesce( try_to_number(nullif(regexp_replace(MRP, \'[^0-9.-]\', \'\'), \'\')), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) ) as MRP, sum( coalesce( try_to_number( nullif( regexp_replace(grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\' ) ), 0 ) * coalesce( try_to_number( nullif(regexp_replace(quantity, \'[^0-9.-]\', \'\'), \'\') ), 0 ) ) as cp from main a left join cost_price_map b on trim( upper( REVERSE( SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code) ) ) ) ) = b.sku_group left join snitch_db.maplemonk.AVG_GT_CHARGES c on b.category = c.category where UPPER(channel_ledger) not in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\', \'CUSTOM\', \'AMAZON_SAPL_TAURU\', \'B2B CORPORATE CHANNEL\', \'SAPL_WH_TRANSFERS\' ) and UPPER(channel_ledger) not like \'%STORE%\' and UPPER(channel_ledger) not like \'%SNITCH%\' group by 1, 2, 3, 4 ), mp_return_sor as ( select \"Display Order Number\" as order_name, trim( upper( REVERSE( SUBSTRING( REVERSE(\"Product SKU Code\"), CHARINDEX(\'-\', REVERSE(\"Product SKU Code\")) + 1, LEN(\"Product SKU Code\") ) ) ) ) AS sku_group, sum(QTY) as return_qty from snitch_db.maplemonk.uc_get_tally_return_gst_report where UPPER(\"Channel Ledger\") not in ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\', \'CUSTOM\', \'AMAZON_SAPL_TAURU\', \'B2B CORPORATE CHANNEL\', \'SAPL_WH_TRANSFERS\' ) and UPPER(\"Channel Ledger\") not like \'%STORE%\' and UPPER(\"Channel Ledger\") not like \'%SNITCH%\' group by 1, 2 ), mp_main_pre_sor as ( select a.*, case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end as return_qty, case when ifnull(b.return_qty, 0) > quantity then \'false\' else \'true\' end as flag, sales * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_sales, mrp * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_mrp, cp * ( ( quantity - case when ifnull(b.return_qty, 0) > quantity then quantity else ifnull(b.return_qty, 0) end ) / quantity ) as net_cp from mp_gross_sor a left join mp_return_sor b on a.order_name = b.order_name and a.sku_group = b.sku_group ), mp_cat_sor as ( select upper( trim( LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))) ) ) AS sku_group, category from snitch_db.maplemonk.uc_final_item_master qualify row_number() over ( partition by upper( trim( LEFT(sku, LENGTH(sku) - CHARINDEX(\'-\', REVERSE(sku))) ) ) order by category desc ) = 1 ), mp_main_sor as ( select a.date, a.sku_group, coalesce(b.category, c.category) as category, \'MP SOR\' Channel, sum(quantity) as quantity, sum(quantity - return_qty) as net_quantity, sum(sales) as sales, sum(net_sales) as net_sales, sum(mrp - sales) as discount, sum(net_mrp - net_sales) as net_discount, sum(cp) as cost_price, sum(net_cp) as net_cost_price from mp_main_pre_sor a left join cost_price_map b on a.sku_group = b.sku_group left join mp_cat_sor c on a.sku_group = c.sku_group group by 1, 2, 3, 4 ), base as ( select * from shopify_main union all select * from offline_main union all select * from mp_main union all select * from flipkart_sor union all select * from myntra_sor union all select * from slikk ), base_filtered as ( select b.* from base b join params p on 1 = 1 where b.date <= p.as_of_date ), meta_map_1 AS ( SELECT UPPER(SKU_group) AS sku_group, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, max(cogs) as cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku_2 a GROUP BY 1 ), meta_map_2 AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, max(cogs) as cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku_2 a GROUP BY 1 ) select date, sku_group, channel, COALESCE(m1.l1_category, m2.l1_category) AS l1_category, COALESCE(m1.category, m2.category) AS meta_category, COALESCE(m1.meta1, m2.meta1) AS meta1, COALESCE(m1.meta2, m2.meta2) AS meta2, COALESCE(m1.meta3, m2.meta3) AS meta3, sum(quantity)::number as quantity, sum(sales)::number as sales, sum(discount)::number as discount, sum(cost_price)::number as cost_price, sum(net_quantity)::number as net_quantity, sum(net_sales)::number as net_sales, sum(net_discount)::number as net_discount, sum(net_cost_price)::number as net_cost_price from base_filtered f LEFT JOIN meta_map_1 m1 using(sku_group) LEFT JOIN meta_map_2 m2 ON UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) = m2.sku_group_clean where date >=\'2026-01-01\' group by 1, 2, 3, 4, 5, 6, 7, 8;",
                    "transaction": true
                }
            ) }}
